import{test}from'node:test';import assert from'node:assert/strict';import*as T from'three';import{fixFoundation}from'../src/foundation.js';
test('foundation replaces striped imported maps with matte concrete without changing facade geometry',()=>{const root=new T.Group(),old=new T.MeshStandardMaterial({name:'COURT_DampFoundation',map:new T.Texture()}),mesh=new T.Mesh(new T.BoxGeometry(26,.5,.2),old);mesh.position.set(13,.25,-4);root.add(mesh);const positions=Array.from(mesh.geometry.attributes.position.array);fixFoundation(root);assert.equal(mesh.material.metalness,0);assert.equal(mesh.material.roughness,1);assert.notEqual(mesh.material,old);assert.deepEqual(Array.from(mesh.geometry.attributes.position.array),positions);for(const v of mesh.geometry.attributes.uv.array)assert.ok(Number.isFinite(v));});
